∀ {M : Type u_1} [inst : Add M] {r : M → M → Prop} {motive : (a a_1 : M) → AddConGen.Rel r a a_1 → Prop} {a a_1 : M}
  (t : AddConGen.Rel r a a_1),
  (∀ (a a_2 : M) (t : AddConGen.Rel r a a_2), AddConGen.Rel.below t → motive a a_2 t) → motive a a_1 t

∀ {G : Type u_1} {H : Type u_2} {inst : Add G} {inst_1 : Add H} {a : G} {b : H} {toEquiv : G ≃ H}
  {map_add_const' : ∀ (x : G), toEquiv.toFun (x + a) = toEquiv.toFun x + b} {toEquiv_1 : G ≃ H}
  {map_add_const'_1 : ∀ (x : G), toEquiv_1.toFun (x + a) = toEquiv_1.toFun x + b},
  { toEquiv := toEquiv, map_add_const' := map_add_const' } =
      { toEquiv := toEquiv_1, map_add_const' := map_add_const'_1 } →
    toEquiv = toEquiv_1

∀ {G : Type u_1} {H : Type u_3} {K : Type u_2} [inst : Add G] [inst_1 : Add H] [inst_2 : Add K] {a : G} {b : H} {c : K}
  (e₁ : AddConstEquiv G H a b) (e₂ : AddConstEquiv H K b c),
  Function.Semiconj (⇑e₂ ∘ ⇑e₁) (fun x => x + a) fun x => x + c

∀ {G : Type u_1} {H : Type u_2} [inst : AddCommGroup G] [inst_1 : AddCommGroup H] {a : G} {b : H}
  (x : AddConstMap G H a b),
  { toFun := fun x_1 => -{ toFun := fun x_2 => -x (-x_2), map_add_const' := ⋯ } (-x_1), map_add_const' := ⋯ } = x

∀ {G : Type u_1} {H : Type u_2} [inst : Add G] [inst_1 : Add H] {a : G} {b : H} (toFun toFun_1 : G → H)
  (e_toFun : toFun = toFun_1) (map_add_const' : ∀ (x : G), toFun (x + a) = toFun x + b),
  { toFun := toFun, map_add_const' := map_add_const' } = { toFun := toFun_1, map_add_const' := ⋯ }

∀ {G : Type u_1} {H : Type u_2} {inst : Add G} {inst_1 : Add H} {a : G} {b : H} {toFun : G → H}
  {map_add_const' : ∀ (x : G), toFun (x + a) = toFun x + b} {toFun_1 : G → H}
  {map_add_const'_1 : ∀ (x : G), toFun_1 (x + a) = toFun_1 x + b},
  { toFun := toFun, map_add_const' := map_add_const' } = { toFun := toFun_1, map_add_const' := map_add_const'_1 } →
    toFun = toFun_1

∀ {M₁ : Type u_5} {M₂ : Type u_6} {N : Type u_8} [inst : AddZeroClass M₁] [inst_1 : AddZeroClass M₂]
  [inst_2 : AddCommMonoid N] (e : M₁ ≃+ M₂),
  e.addMonoidHomCongrLeft = { toEquiv := e.addMonoidHomCongrLeftEquiv, map_add' := ⋯ }

∀ {M : Type u_4} {N₁ : Type u_9} {N₂ : Type u_10} [inst : AddZeroClass M] [inst_1 : AddCommMonoid N₁]
  [inst_2 : AddCommMonoid N₂] (e : N₁ ≃+ N₂),
  e.addMonoidHomCongrRight = { toEquiv := e.addMonoidHomCongrRightEquiv, map_add' := ⋯ }
